import React, { useState } from "react";
import { motion } from "framer-motion";
import { momentSections } from "../moments";
import Lightbox from "../components/Lightbox";
import Page from "../components/Page";
import { lineAnim, rise } from "../animation";

export default function Moments() {
  const [open, setOpen] = useState(null);

  const section = open ? momentSections.find((item) => item.id === open.sectionId) : null;

  function step(direction) {
    if (!section) {
      return;
    }
    const count = section.photos.length;
    setOpen((current) => ({
      sectionId: current.sectionId,
      index: (current.index + direction + count) % count,
    }));
  }

  return (
    <Page wide>
      <div className="rise">
        <motion.h1 variants={rise}>Special Moments</motion.h1>
      </div>
      <motion.div className="rule" variants={lineAnim} />
      <motion.p className="lede" variants={rise}>
        A few memories from my academic journey, teaching experiences, and life during my Ph.D.
      </motion.p>
      {momentSections.map((group) => (
        <section className="moment-section" key={group.id} aria-labelledby={group.id}>
          <h2 id={group.id}>{group.title}</h2>
          <ul className="moment-grid">
            {group.photos.map((photo, index) => (
              <li key={photo.src}>
                <button
                  type="button"
                  className="moment-thumb"
                  onClick={() => setOpen({ sectionId: group.id, index })}
                >
                  <img
                    src={photo.src}
                    alt={photo.alt}
                    width={photo.width}
                    height={photo.height}
                    loading="lazy"
                  />
                </button>
              </li>
            ))}
          </ul>
        </section>
      ))}
      {section ? (
        <Lightbox
          photos={section.photos}
          index={open.index}
          onClose={() => setOpen(null)}
          onStep={step}
        />
      ) : null}
    </Page>
  );
}
