import React from "react";
import { motion } from "framer-motion";
import { newsByYear } from "../content";
import Page from "../components/Page";
import { lineAnim, rise } from "../animation";

export default function News() {
  const groups = newsByYear();

  return (
    <Page>
      <div className="rise">
        <motion.h1 variants={rise}>News</motion.h1>
      </div>
      <motion.div className="rule" variants={lineAnim} />
      <motion.p className="lede" variants={rise}>
        Announcements from research, teaching, and earlier milestones.
      </motion.p>
      {groups.map((group) => (
        <section className="news-year" key={group.year} aria-labelledby={`year-${group.year}`}>
          <h2 id={`year-${group.year}`}>{group.year}</h2>
          <ol className="news-timeline">
            {group.items.map((item) => (
              <li key={item.id}>
                <p className="meta">{item.displayDate}</p>
                <h3>{item.title}</h3>
                <p>{item.description}</p>
                {item.links.length ? (
                  <ul className="resource-links">
                    {item.links.map((link) => (
                      <li key={link.href}>
                        <a href={link.href} target="_blank" rel="noopener noreferrer">
                          {link.label}
                        </a>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </li>
            ))}
          </ol>
        </section>
      ))}
    </Page>
  );
}
